(function () {
  'use strict';

  /* ---------- 設計データ（base-pairs.csv / dna-accesories.kicad_pcb）由来 ---------- */
  // [ref, pair no., strand (A=sense / B=complement), X mm, Y mm]  ordered as the DIN->DOUT data chain
  /* generated by gen/make_lp_images.py: do not edit by hand */
  var LEDS = [
    ['U2',1,'A',102.75,70],['U3',1,'B',97.25,70],['U4',2,'A',102.75,74],['U5',2,'B',97.25,74],
    ['U6',3,'A',97.25,78],['U7',3,'B',102.75,78],['U8',4,'A',97.25,82],['U9',4,'B',102.75,82],
    ['U10',5,'A',97.25,86],['U11',5,'B',102.75,86],['U12',6,'A',102.75,90],['U13',6,'B',97.25,90],
    ['U14',7,'A',102.75,94],['U15',7,'B',97.25,94],['U16',8,'A',102.75,98],['U17',8,'B',97.25,98],
    ['U18',9,'A',97.25,102],['U19',9,'B',102.75,102],['U20',10,'A',97.25,106],['U21',10,'B',102.75,106],
    ['U22',11,'A',97.25,110],['U23',11,'B',102.75,110],['U24',12,'A',102.75,114],['U25',12,'B',97.25,114]
  ];
  // board outline (Edge.Cuts) <-> 3D render board-top.png (984x3366px, cropped to the board)
  var BX0 = 88, BW = 24, BY0 = 68.4012;
  var PX_PER_MM = 984 / BW, IMG_W = 984, IMG_H = 3366, IMG_TOP = 0;
  var PAIR_Y0 = 70.0000, PAIR_PITCH = 4;   // first base-pair row and row pitch (mm)
  function xPct(x) { return (x - BX0) / BW * 100; }
  function yPct(y) { return (IMG_TOP + (y - BY0) * PX_PER_MM) / IMG_H * 100; }
  /* end generated */

  var COLOR = { A: '#46f0a0', T: '#ff5a7a', G: '#ffc247', C: '#4aa8ff' };
  var COMP = { A: 'T', T: 'A', G: 'C', C: 'G' };

  /* ---------- 標準遺伝暗号（アミノ酸 1 文字コード → コドン） ---------- */
  var CODE = {
    F: ['TTT','TTC'], L: ['TTA','TTG','CTT','CTC','CTA','CTG'], I: ['ATT','ATC','ATA'], M: ['ATG'],
    V: ['GTT','GTC','GTA','GTG'], S: ['TCT','TCC','TCA','TCG','AGT','AGC'], P: ['CCT','CCC','CCA','CCG'],
    T: ['ACT','ACC','ACA','ACG'], A: ['GCT','GCC','GCA','GCG'], Y: ['TAT','TAC'], H: ['CAT','CAC'],
    Q: ['CAA','CAG'], N: ['AAT','AAC'], K: ['AAA','AAG'], D: ['GAT','GAC'], E: ['GAA','GAG'],
    C: ['TGT','TGC'], W: ['TGG'], R: ['CGT','CGC','CGA','CGG','AGA','AGG'], G: ['GGT','GGC','GGA','GGG'],
    '*': ['TAA','TAG','TGA']
  };
  var NAMES = { F:'フェニルアラニン',L:'ロイシン',I:'イソロイシン',M:'メチオニン',V:'バリン',S:'セリン',P:'プロリン',T:'トレオニン',
    A:'アラニン',Y:'チロシン',H:'ヒスチジン',Q:'グルタミン',N:'アスパラギン',K:'リシン',D:'アスパラギン酸',E:'グルタミン酸',
    C:'システイン',W:'トリプトファン',R:'アルギニン',G:'グリシン','*':'終止' };
  var LETTERS = 'ACDEFGHIKLMNPQRSTVWY';
  var REV = {};
  Object.keys(CODE).forEach(function (a) { CODE[a].forEach(function (c) { REV[c] = a; }); });

  function pick(letter, variant) { var l = CODE[letter]; return l[((variant % l.length) + l.length) % l.length]; }
  function buildCodons(word, variant) {
    var out = [], i;
    for (i = 0; i < 4; i++) out.push(i < word.length ? pick(word[i], variant) : pick('*', variant + (i - word.length)));
    return out;
  }
  function $(s, r) { return (r || document).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
  function bases(codon) { return codon.split('').map(function (b) { return '<b data-b="' + b + '">' + b + '</b>'; }).join(''); }
  function wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---------- 基板（LED グロー付き） ---------- */
  function Board(el) {
    this.el = el; this.leds = []; this.brackets = []; this.token = 0;
    var self = this, halo = document.createElement('div');
    halo.className = 'halo'; el.appendChild(halo);
    LEDS.forEach(function (d) {
      var n = document.createElement('i');
      n.className = 'led'; n.style.left = xPct(d[3]) + '%'; n.style.top = yPct(d[4]) + '%';
      n.title = d[0]; halo.appendChild(n); self.leds.push(n);
    });
    for (var k = 0; k < 4; k++) {
      var y1 = yPct(PAIR_Y0 + k * 3 * PAIR_PITCH) - 1.1, y2 = yPct(PAIR_Y0 + (k * 3 + 2) * PAIR_PITCH) + 1.1;
      var b = document.createElement('div'); b.className = 'bracket';
      b.style.top = y1 + '%'; b.style.height = (y2 - y1) + '%';
      b.innerHTML = '<span>CODON ' + (k + 1) + '<br>PAIR ' + (k * 3 + 1) + '–' + (k * 3 + 3) + '</span>';
      el.appendChild(b); this.brackets.push(b);
    }
  }
  Board.prototype.ledColor = function (i, codons) {
    var d = LEDS[i], c = codons[Math.floor((d[1] - 1) / 3)], b = c[(d[1] - 1) % 3];
    return d[2] === 'A' ? b : COMP[b];
  };
  Board.prototype.clear = function () {
    this.token++;
    this.leds.forEach(function (n) { n.classList.remove('on'); });
    this.brackets.forEach(function (b) { b.classList.remove('on'); });
  };
  // codons: 4 つのコドン。animate=true で DIN→DOUT の順に 1 個ずつ点灯。onCodon(k) は各コドン点灯完了時
  Board.prototype.show = function (codons, animate, onCodon) {
    var self = this, t = ++this.token;
    this.leds.forEach(function (n) { n.classList.remove('on'); });
    this.brackets.forEach(function (b) { b.classList.remove('on'); });
    return (async function () {
      for (var i = 0; i < LEDS.length; i++) {
        if (t !== self.token) return false;
        var n = self.leds[i], c = COLOR[self.ledColor(i, codons)];
        n.style.setProperty('--c', c);
        n.classList.add('on');
        var k = Math.floor(i / 6);
        self.brackets[k].classList.add('on');
        if (animate && !reduce) await wait(i % 6 === 5 ? 120 : 85);
        if (i % 6 === 5 && onCodon) onCodon(k);
      }
      return t === self.token;
    })();
  };

  /* ---------- ヒーロー ---------- */
  var heroEl = $('#heroBoard');
  if (heroEl) {
    var hb = new Board(heroEl);
    var cards = $$('#readout .codon'), msg = $('#heroMsg');
    var WORDS = ['MAS', 'LIFE', 'DNA', 'GIFT', 'WISH'];
    var first = true, wi = 0;
    var reset = function () {
      cards.forEach(function (c) {
        c.classList.remove('on'); $('.l', c).textContent = '?';
        $$('b', c).forEach(function (b) { b.textContent = '·'; b.removeAttribute('data-b'); b.classList.remove('on'); });
      });
    };
    var loop = async function () {
      for (;;) {
        var word = WORDS[wi % WORDS.length]; wi++;
        // 先頭の例は基板シルクと同じ配列 ATG GCA TCG TAA（= M A S ■）
        var codons = first ? ['ATG', 'GCA', 'TCG', 'TAA'] : buildCodons(word, wi);
        var shown = first ? 'MAS' : word; first = false;
        reset(); msg.innerHTML = 'MESSAGE &nbsp;<strong>' + '· '.repeat(1) + '</strong>';
        var out = '';
        var done = await hb.show(codons, true, function (k) {
          var aa = REV[codons[k]], card = cards[k];
          card.classList.add('on'); card.style.setProperty('--glow', COLOR[codons[k][1]]);
          $('.l', card).textContent = aa === '*' ? '■' : aa;
          $$('b', card).forEach(function (b, j) { b.textContent = codons[k][j]; b.setAttribute('data-b', codons[k][j]); b.classList.add('on'); });
          if (aa !== '*') out += aa;
          msg.innerHTML = 'MESSAGE &nbsp;<strong>' + out + '</strong>';
        });
        if (!done) return;
        await wait(reduce ? 4000 : 3200);
        hb.clear(); await wait(500);
      }
    };
    loop();
  }

  /* ---------- コドン表 ---------- */
  var tbl = $('#table');
  if (tbl) {
    tbl.innerHTML = LETTERS.split('').concat(['*']).map(function (a) {
      return '<button class="cell' + (a === '*' ? ' stop' : '') + '" data-a="' + a + '" type="button">' +
        '<span class="L">' + (a === '*' ? '■' : a) + '</span><span class="aa">' + NAMES[a] + '</span>' +
        '<div class="cs cx">' + CODE[a].map(function (c) { return '<span>' + bases(c) + '</span>'; }).join('') + '</div></button>';
    }).join('');
  }

  /* ---------- 体験デモ ---------- */
  var demoEl = $('#demoBoard');
  if (demoEl) {
    var db = new Board(demoEl), input = $('#word'), slots = $$('#slots .slot'), hint = $('#hint');
    var variant = 0;
    var sanitize = function (s) {
      var ok = '', bad = '';
      s.toUpperCase().split('').forEach(function (ch) {
        if (/\s/.test(ch)) return;
        if (LETTERS.indexOf(ch) >= 0) ok += ch; else bad += ch;
      });
      return { ok: ok.slice(0, 4), bad: bad, over: ok.length > 4 };
    };
    var render = function (animate) {
      var s = sanitize(input.value), w = s.ok;
      if (input.value.toUpperCase() !== w) input.value = w;
      var msgs = [];
      if (s.bad) msgs.push('「' + s.bad.split('').filter(function (c, i, a) { return a.indexOf(c) === i; }).join('') + '」はアミノ酸コードに無い文字です（使えない: B J O U X Z）');
      if (s.over) msgs.push('基板は 4 コドン分。先頭の 4 文字までを表示します');
      hint.textContent = msgs.join(' / ');
      if (!w) {
        db.clear();
        slots.forEach(function (sl) { sl.classList.remove('on'); $('.big', sl).textContent = '–'; $('.seq', sl).innerHTML = ''; $('.seq.c', sl).innerHTML = ''; $('.tag', sl).textContent = '文字を入力してください'; });
        return;
      }
      var cod = buildCodons(w, variant);
      slots.forEach(function (sl, k) {
        var c = cod[k], aa = REV[c], stop = aa === '*';
        sl.classList.add('on'); sl.style.borderColor = COLOR[c[1]] + '88';
        $('.big', sl).textContent = stop ? '■' : aa;
        $('.big', sl).style.color = stop ? '#ff8a9c' : '#fff';
        $('.seq', sl).innerHTML = bases(c);
        $('.seq.c', sl).innerHTML = bases(c.split('').map(function (b) { return COMP[b]; }).join(''));
        $('.tag', sl).textContent = (stop ? 'STOP（終止）' : NAMES[aa]) + (CODE[aa].length > 1 ? ' ／ 同義コドン ' + CODE[aa].length + ' 種' : ' ／ 唯一のコドン');
      });
      db.show(cod, animate !== false);
    };
    input.addEventListener('input', function () { render(true); });
    $$('.chip').forEach(function (c) { c.addEventListener('click', function () { input.value = c.dataset.w; variant = 0; render(true); }); });
    $('#alt').addEventListener('click', function () { variant++; render(true); });
    $('#replay').addEventListener('click', function () { render(true); });
    tbl && tbl.addEventListener('click', function (e) {
      var b = e.target.closest('.cell'); if (!b || b.dataset.a === '*') return;
      var w = sanitize(input.value).ok; input.value = (w.length >= 4 ? w.slice(0, 3) : w) + b.dataset.a;
      render(true); $('#demo').scrollIntoView({ behavior: reduce ? 'auto' : 'smooth' });
    });
    input.value = 'LIFE'; render(false);
    // 画面に入ったら一度点灯演出
    if ('IntersectionObserver' in window) {
      var seen = false;
      new IntersectionObserver(function (es) { if (es[0].isIntersecting && !seen) { seen = true; render(true); } }, { threshold: .35 }).observe(demoEl);
    }
  }

  /* ---------- スクロール表示 ---------- */
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (es) {
      es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });
    }, { threshold: .12 });
    $$('.rv').forEach(function (n) { io.observe(n); });
  } else { $$('.rv').forEach(function (n) { n.classList.add('in'); }); }
})();

/* ---------- 活用シーン動画：画面に入ったら読み込み・再生 ---------- */
(function () {
  var vs = Array.prototype.slice.call(document.querySelectorAll('.sc video'));
  if (!vs.length) return;
  var rm = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (rm || !('IntersectionObserver' in window)) return; // ポスター画像のまま表示
  var io = new IntersectionObserver(function (es) {
    es.forEach(function (e) {
      var v = e.target;
      if (e.isIntersecting) {
        if (!v.src) { v.src = v.dataset.src; v.addEventListener('error', function () { v.removeAttribute('src'); }); }
        var p = v.play(); if (p && p.catch) p.catch(function () {});
      } else { v.pause(); }
    });
  }, { threshold: .35 });
  vs.forEach(function (v) { io.observe(v); });
})();
